head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/** 페이지 이동 */
/**
 * @method
 * @name goURL
 * @description desc
 * @param {string} _url desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.goURL = function(_url) {
    document.location.href = _url;
};


/** 팝업 */
/**
 * @method
 * @name pop
 * @description desc
 * @param {string} _url desc
 * @param {string} _name desc
 * @param {string} _addProps desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.pop = function(_url, _name, _addProps) {
    var props = "toolbar=no,menubar=no,scrollbars=no,status=yes,resizable=yes";
    if (typeof(_addProps) == "undefined" || _addProps == "") {
        props += ",width=500,height=300";
    } else {
        props += _addProps;
    }

    //window.open(_url, _name, props);

    //var winTitle ="선택추출";
    //frame.CreateDialogFrame(_name, _url , winTitle ,10, 10, 300, 400, "window");	
    $c.frame.path('/').OuterWindow.window.open(_url, _name, props);
};


/** json객체 */
JSON = function(jsonText) {
    this.json = eval("(" + jsonText + ")");
};
JSON.prototype.getValue = function(attr) {
    var val = eval("this.json." + attr);
    if (val == undefined) return "";
    return val;
};


/** str.trim() */
String.prototype.trim = function() {
    return this.replace(/^ *| *$/g, "");
};


/** 유효성검사 object */
InputValidation = function(formName) {
    this.formName = formName;
    this.fixLengthItemList = new Array();
    this.requiredItemList = new Array();
};


/** 유효성검사 - 길이가 지정된 항목 */
FixLengthItem = function(inputName, fixLength, alertMessage) {
    this.inputName = inputName;
    this.fixLength = fixLength;
    this.alertMessage = alertMessage;
};


/** 유효성검사 - 필수 항목 */
RequiredItem = function(inputName, alertMessage) {
    this.inputName = inputName;
    this.alertMessage = alertMessage;
};
InputValidation.prototype.addFixLengthItem = function(inputName, fixLength, alertMessage) {
    this.fixLengthItemList[this.fixLengthItemList.length] = new FixLengthItem(inputName, fixLength, alertMessage);
};
InputValidation.prototype.addRequiredItem = function(inputName, alertMessage) {
    this.requiredItemList[this.requiredItemList.length] = new RequiredItem(inputName, alertMessage);
};


/** 유효성검사 */
InputValidation.prototype.isValid = function() {
    var message = "";
    var inputObjList = new Array();
    var valid = true;
    for (var i = 0; i < this.fixLengthItemList.length; i++) {
        var inputName = this.fixLengthItemList[i].inputName;
        var fixLength = this.fixLengthItemList[i].fixLength;
        var alertMessage = this.fixLengthItemList[i].alertMessage;
        if ($c.ut.trim().length != fixLength) {
            valid = false;
            message += alertMessage + "\n";
            inputObjList[inputObjList.length] = eval(this.formName + "." + inputName);
        }
    }
    for (var i = 0; i < this.requiredItemList.length; i++) {
        var inputName = this.requiredItemList[i].inputName;
        var alertMessage = this.requiredItemList[i].alertMessage;
        if ($c.ut.trim().length == 0) {
            valid = false;
            message += alertMessage + "\n";
            inputObjList[inputObjList.length] = eval(this.formName + "." + inputName);
        }
    }
    var firstInputObj;
    var formObj = eval(this.formName);
    var findFirst = false;
    for (var i = 0; i < formObj.elements.length; i++) {
        for (var j = 0; j < inputObjList.length; j++) {
            if (formObj.elements[i] == inputObjList[j]) {
                firstInputObj = formObj.elements[i];
                findFirst = true;
                break;
            }
        }
        if (findFirst) break;
    }
    if (!valid) {
        alert(message);
        firstInputObj.focus();
    }
    return valid;
};


/*=============================================================================*
 * 입력값이 숫자인지를 확인한다
 * param : sVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name rtnNumber
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.rtnNumber = function(sVal) {
    var rtnVal = "";
    if (sVal.length < 1) {
        return rtnVal;
    }
    for (i = 0; i < sVal.length; i++) {
        iBit = parseInt(sVal.substring(i, i + 1)); //문자(Char)를 숫자로 변경
        if (('0' <= iBit) && ('9' >= iBit)) {
            rtnVal = rtnVal + iBit;
        }
    }
    return rtnVal;
};


/*=============================================================================*
 * 날짜컬럼에 포커스들어갈경우 "-" 제거해준다
 * param : sdateVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name cal_offMask
 * @description desc
 * @param {string} sdateVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cal_offMask = function(sdateVal) {
    var dateVal = eval(sdateVal).getValue();
    if (dateVal.length < 1) {
        return false;
    }
    eval(sdateVal).setValue("");
    eval(sdateVal).setValue(dateVal.replace(/\-/g, ''));
};


/*=============================================================================*
 * 입력값이 숫자인지를 확인하고 포멧을 만들어준다
 * param : sdateVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name chkDate
 * @description desc
 * @param {string} sdateVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkDate = function(sdateVal) {
    var dateVal = eval(sdateVal).getValue();
    if (dateVal.length < 1) {
        return;
    }
    var dateVal2 = scwin.rtnNumber(dateVal);
    window.status = dateVal2.length;
    if (dateVal2.length < 1) {
        eval(sdateVal).setValue("");
    } else if (dateVal2.length >= 1 && dateVal2.length < 8) {
        eval(sdateVal).setValue(dateVal2);
    } else if (dateVal2.length == 8) {
        eval(sdateVal).setValue(dateVal2.substring(0, 4) + "-" + dateVal2.substring(4, 6) + "-" + dateVal2.substring(6, 8));
    } else if (dateVal2.length > 8) {
        eval(sdateVal).setValue(dateVal2.substring(0, 4) + "-" + dateVal2.substring(4, 6) + "-" + dateVal2.substring(6, 8));
    }
};



/*=============================================================================*
 * 날짜컬럼에 포커스들어갈경우 ":" 제거해준다
 * param : sdateVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name cal_offMask2
 * @description desc
 * @param {string} sdateVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cal_offMask2 = function(sdateVal) {
    var dateVal = eval(sdateVal).getValue();
    if (dateVal.length < 1) {
        return false;
    }
    eval(sdateVal).setValue("");
    eval(sdateVal).setValue(dateVal.replace(/\:/g, ''));
};


/*=============================================================================*
 * 입력값이 숫자인지를 확인하고 포멧을 만들어준다
 * param : sdateVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name chkDate2
 * @description desc
 * @param {string} sdateVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkDate2 = function(sdateVal) {
    var dateVal = eval(sdateVal).getValue();
    if (dateVal.length < 1) {
        return;
    }
    var dateVal2 = scwin.rtnNumber(dateVal);
    window.status = dateVal2.length;
    if (dateVal2.length < 1) {
        eval(sdateVal).setValue("");
    } else if (dateVal2.length >= 1 && dateVal2.length < 6) {
        eval(sdateVal).setValue(dateVal2);
    } else if (dateVal2.length == 6) {
        eval(sdateVal).setValue(dateVal2.substring(0, 2) + ":" + dateVal2.substring(2, 4) + ":" + dateVal2.substring(4, 6));
    } else if (dateVal2.length > 6) {
        eval(sdateVal).setValue(dateVal2.substring(0, 2) + ":" + dateVal2.substring(2, 4) + ":" + dateVal2.substring(4, 6));
    }
};
